# Generated by Neuralese. Do not edit -- export again to change it.
#
# Robot: LEGO SPIKE Prime running Pybricks
# Link:  USB serial (plug the hub into the computer with a data cable)
#
# This program does not contain the neural network. It reads the sensors, sends
# the readings to the computer, and does what the computer sends back. The
# computer runs the model. That is why this program never has to change when you
# train a new model -- only when you choose different sensors or motors.
#
# Safety: if the computer stops answering for 300 ms, every motor is
# stopped automatically.
#
# Needs the Pybricks firmware on the hub (pybricks.com/install). LEGO's own SPIKE
# app firmware will not run this program.

from pybricks.hubs import PrimeHub
from pybricks.parameters import Color
from pybricks.tools import StopWatch, wait
from uselect import poll
from usys import stdin, stdout
from pybricks.pupdevices import ColorSensor
from pybricks.parameters import Port
from pybricks.pupdevices import UltrasonicSensor
from pybricks.pupdevices import Motor

PROTOCOL = 1
PLATFORM = "spike"
CFG_HASH = "368b50dd"
N_IN = 2
N_OUT = 2
RATE_HZ = 20
PERIOD_MS = 50
WATCHDOG_MS = 300
SEQ_MOD = 10000
MAX_LINE = 240
SAFE = [0, 0]

_hub = PrimeHub()
_clock = StopWatch()

_color_a = ColorSensor(Port.A)
_ultrasonic_b = UltrasonicSensor(Port.B)
_motor_e = Motor(Port.E)

_HUB_COLORS = (None, Color.RED, Color.GREEN, Color.BLUE, Color.YELLOW, Color.WHITE)

# Repeating an unchanged motor command every frame is wasted work on the hub,
# and re-issuing a duty cycle can make a motor buzz. Only write on change.
_last_motor_command = {}


def _drive_motor(motor, percent):
    percent = max(-100, min(100, int(percent)))
    if _last_motor_command.get(id(motor)) == percent:
        return
    if percent == 0:
        motor.stop()
    else:
        motor.dc(percent)
    # Remembered only after the call succeeded. Recording it first would leave
    # this believing the motor had stopped when it had not, so a retry would
    # return early and the motor would keep running.
    _last_motor_command[id(motor)] = percent


def _set_hub_light(index):
    index = max(0, min(len(_HUB_COLORS) - 1, int(index)))
    color = _HUB_COLORS[index]
    if color is None:
        _hub.light.off()
    else:
        _hub.light.on(color)


def _crc(text):
    total = 0
    for char in text:
        total += ord(char)
    return total & 0xFFFF


def _send(payload):
    stdout.buffer.write((payload + "," + ("%04x" % _crc(payload)) + "\n").encode())


def _parse(line):
    # Returns the split fields, or None if the line is damaged. A half-received
    # line must never be acted on: it can decode as a plausible motor command.
    index = line.rfind(",")
    if index < 0:
        return None
    head = line[:index]
    try:
        if int(line[index + 1:], 16) != _crc(head):
            return None
    except Exception:
        return None
    return head.split(",")


def read_sensors():
    return [
        _color_a.reflection(),  # Colour sensor (port A) reflection
        _ultrasonic_b.distance(),  # Distance sensor (port B)
    ]


def apply_outputs(values):
    _drive_motor(_motor_e, values[0])  # Motor E speed
    _set_hub_light(values[1])  # Hub light colour


def safe_stop():
    apply_outputs(SAFE)


_keyboard = poll()
_keyboard.register(stdin)
_buffer = ""


def pump():
    """Move whatever arrived on USB into the line buffer, without blocking."""
    global _buffer
    while _keyboard.poll(0):
        char = stdin.buffer.read(1)
        if not char:
            break
        _buffer += char.decode()
    if len(_buffer) > MAX_LINE and "\n" not in _buffer:
        # Noise with no line ending. Throw it away rather than grow forever.
        _buffer = ""


def take_line():
    global _buffer
    if "\n" not in _buffer:
        return None
    line, _buffer = _buffer.split("\n", 1)
    return line.strip()


# --- connect ---------------------------------------------------------------
# Say hello until the computer answers. Nothing moves until it does.

hello = "H,%d,%s,%s,%d,%d,%d,%d" % (
    PROTOCOL, PLATFORM, CFG_HASH, N_IN, N_OUT, RATE_HZ, WATCHDOG_MS)

_hub.light.on(Color.YELLOW)
connected = False
last_hello = -10000

while not connected:
    now = _clock.time()
    if now - last_hello >= 250:
        _send(hello)
        last_hello = now
    pump()
    while True:
        line = take_line()
        if line is None:
            break
        fields = _parse(line)
        if not fields:
            continue
        if fields[0] == "K":
            connected = True
        elif fields[0] == "E":
            safe_stop()
            _hub.light.on(Color.RED)
            while True:
                wait(1000)
    wait(10)

_hub.light.on(Color.GREEN)

# --- run -------------------------------------------------------------------

seq = 0
last_send = _clock.time()
last_command = _clock.time()
stopped = False
running = True

while running:
    now = _clock.time()

    pump()
    while running:
        line = take_line()
        if line is None:
            break
        fields = _parse(line)
        if not fields:
            continue
        kind = fields[0]
        if kind == "A" and len(fields) == N_OUT + 2:
            try:
                values = [int(field) for field in fields[2:]]
            except Exception:
                continue
            apply_outputs(values)
            last_command = now
            stopped = False
        elif kind == "K":
            # A fresh computer accepted us after the old one went away.
            last_command = now
            stopped = False
            _hub.light.on(Color.GREEN)
        elif kind == "X":
            safe_stop()
            _hub.light.off()
            running = False
        elif kind == "E":
            safe_stop()
            _hub.light.on(Color.RED)
            while True:
                wait(1000)

    if not running:
        break

    # Watchdog. The computer answers every reading, so silence means the link
    # is gone -- and a robot that keeps its last motor command after losing the
    # link is a robot that drives into something.
    if not stopped and now - last_command > WATCHDOG_MS:
        safe_stop()
        stopped = True
        _hub.light.on(Color.ORANGE)

    if stopped and now - last_hello >= 250:
        # The computer has gone. Start announcing ourselves again so that when
        # Neuralese comes back it can complete a fresh handshake -- it is not
        # allowed to act on sensor readings from a robot it has not agreed a
        # mapping with, so without this a reconnect would never take.
        _send(hello)
        last_hello = now

    if now - last_send >= PERIOD_MS:
        last_send = now
        seq = (seq + 1) % SEQ_MOD
        payload = "S," + str(seq)
        for value in read_sensors():
            payload += "," + str(int(value))
        _send(payload)

    wait(2)

safe_stop()
